PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?emotionLabel ?sicilianWord ?parmigianoWord
WHERE {
    GRAPH <http://liita.it/data> {
        ?italianLemma a lila:Lemma ;
                      ontolex:writtenRep ?italianWord .
    }

    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
        ?emotion rdfs:label ?emotionLabel .
        FILTER(REGEX(STR(?emotionLabel), "gioia|fiducia|anticipazione", "i"))
    }

    ?sicilianEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .
    ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
    ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?sicilianWord .

    ?parmigianoEntry ontolex:canonicalForm ?italianLemma ;
                     vartrans:translatableAs ?parmigianoLexEntry .
    ?parmigianoLexEntry ^lime:entry <http://liita.ilc.cnr.it/data/id/LexicalReources/DialettoParmigiano/Lexicon> ;
                     ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma ontolex:writtenRep ?parmigianoWord .
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:float(?polarityValue)) AS ?avgPolarityValue)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma .
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion elita:Gioia .
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                 marl:hasPolarityValue ?polarityValue .
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (AVG(xsd:float(?polarityValue)) AS ?avgPolarityValue)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma .
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }

  ?polarityEntry ontolex:canonicalForm ?italianLemma .
  ?polarityEntry marl:hasPolarityValue ?polarityValue .

  FILTER(REGEX(STR(?emotionLabel), "tristezza", "i"))
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT DISTINCT ?italianWord ?parmigianoWord ?polarityValue ?polarityLabel
WHERE {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWord ;
                  dcterms:isPartOf <http://liita.it/data/id/lemma/LemmaBank> .

    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarity ?polarity ;
                   marl:hasPolarityValue ?polarityValue .
    ?polarity rdfs:label ?polarityLabel .

    FILTER(STR(?polarityLabel) = "Negative")

    ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                     vartrans:translatableAs ?parmigianoLexEntry .

    ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                     ontolex:writtenRep ?parmigianoWord .
}
ORDER BY ?polarityValue

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(DISTINCT ?italianLemma) as ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma .
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }

  FILTER regex(str(?emotionLabel), "gioia", "i")
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?emotionLabel ?pos (COUNT(*) as ?count)
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  lila:hasPOS ?pos .
  }

  ?emotionEntry ontolex:canonicalForm ?italianLemma .

  GRAPH <http://w3id.org/elita> {
    ?emotionEntry elita:HasEmotion ?emotion .
    ?emotion rdfs:label ?emotionLabel .
  }
}
GROUP BY ?emotionLabel ?pos
ORDER BY ?emotionLabel DESC(?count)

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>

SELECT ?pos ?emotionLabel (COUNT(DISTINCT ?dialectWord) AS ?count)
WHERE {
    GRAPH <http://liita.it/data> {
        ?italianLemma a lila:Lemma ;
                      lila:hasPOS ?pos .
    }

    ?emotionEntry ontolex:canonicalForm ?italianLemma .

    GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
        ?emotion rdfs:label ?emotionLabel .
    }

    ?translationEntry ontolex:canonicalForm ?italianLemma ;
                      vartrans:translatableAs ?dialectLexEntry .

    ?dialectLexEntry ontolex:canonicalForm ?dialectLemma .

    ?dialectLemma dcterms:isPartOf ?dialectLemmaBank ;
                  ontolex:writtenRep ?dialectWord .

    FILTER(REGEX(STR(?dialectLemmaBank), "Dialetto", "i"))
}
GROUP BY ?pos ?emotionLabel
ORDER BY ?pos ?emotionLabel

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dcterms: <http://purl.org/dc/terms/>
