PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?wholeWord ?partWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?wholeWord ] ;
          ontolex:sense ?wholeSense .

    FILTER(STR(?wholeWord) = "edificio")

    ?partWordEntry ontolex:sense ?partSense ;
                   ontolex:canonicalForm [ ontolex:writtenRep ?partWord ] .

    ?partSense lexinfo:partMeronym ?wholeSense .

    OPTIONAL { ?partSense skos:definition ?definition }
  }
}

