PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?partWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense ?sense .

    FILTER(STR(?writtenRep) = "fiore")

    ?partSense lexinfo:partMeronym ?sense .

    ?partWord ontolex:sense ?partSense ;
              ontolex:canonicalForm [ ontolex:writtenRep ?partWord ] .

    OPTIONAL { ?partSense skos:definition ?definition }
  }
}

PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>

SELECT DISTINCT ?italianWord ?synonym
WHERE {
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
        FILTER(STR(?writtenRep) = "cibo")

        ?word ontolex:sense ?sense .

        { ?sense lexinfo:approximateSynonym ?synonymSense . }
        UNION
        { ?synonymSense lexinfo:approximateSynonym ?sense . }

        ?synonymWord ontolex:sense ?synonymSense ;
                     ontolex:canonicalForm [ ontolex:writtenRep ?synonym ] .
    }

    ?word ontolex:canonicalForm ?italianLemma .

    GRAPH <http://liita.it/data> {
        ?italianLemma a lila:Lemma ;
                      ontolex:writtenRep ?italianWord .
    }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?partWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense ?wholeSense .

    FILTER(STR(?writtenRep) = "edificio")

    ?partSense lexinfo:partMeronym ?wholeSense .

    ?partWord ontolex:sense ?partSense ;
              ontolex:canonicalForm [ ontolex:writtenRep ?partWord ] .

    OPTIONAL { ?partSense skos:definition ?definition }
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>

SELECT DISTINCT ?italianWord ?definition
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word a ontolex:Word ;
          ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense ?sense .
    ?sense skos:definition ?definition .
    FILTER(REGEX(STR(?definition), "mano", "i"))
  }

  ?word ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWord .
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>

SELECT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  lila:hasPOS lila:noun ;
                  ontolex:writtenRep ?italianWord .
    FILTER regex(str(?italianWord), "ità$")
  }
}
ORDER BY ?italianWord

# This query retrieves verbs from the LiITA Lemma Bank whose written representations start with the prefix "ri-".

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?italianWord
WHERE {
  GRAPH <http://liita.it/data> {
    ?lemma a lila:Lemma ;
           ontolex:writtenRep ?italianWord ;
           lila:hasPOS lila:verb .
    FILTER regex(str(?italianWord), "^ri")
  }
}
ORDER BY ?italianWord

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT ?italianWord ?definition
WHERE {
  # Start with SERVICE to get words with definitions and filter
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:sense [ skos:definition ?definition ] ;
          ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] .
    # Filter for words ending in '-ità'
    FILTER(REGEX(STR(?writtenRep), "ità$", "i"))
  }

  # Link to LiIta using shared URI
  ?word ontolex:canonicalForm ?italianLemma .

  # LiIta-specific filters
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  lila:hasPOS lila:noun ;
                  ontolex:writtenRep ?italianWord .
  }
}
ORDER BY ?italianWord

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT (AVG(?formCount) AS ?avgForms)
WHERE {
  GRAPH <http://liita.it/data> {
    {
      SELECT ?italianLemma (COUNT(DISTINCT ?writtenRep) AS ?formCount)
      WHERE {
        ?italianLemma a lila:Lemma ;
                      lila:hasPOS lila:verb ;
                      ontolex:writtenRep ?writtenRep .
      }
      GROUP BY ?italianLemma
    }
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?word
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?italianWord ontolex:canonicalForm [ ontolex:writtenRep ?italianWr ] ;
                 ontolex:sense [ skos:definition ?definition ] .
    FILTER(REGEX(?definition, "donna", "i"))
  }

  ?italianWord ontolex:canonicalForm ?italianLemma .
  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWritten .
  }

  ?italianLexEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .

  ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
  ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                 ontolex:writtenRep ?sicilianWritten .

  FILTER(STR(?italianWritten) = STR(?sicilianWritten))

  BIND(STR(?italianWritten) AS ?word)
}
ORDER BY ?word

PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT (COUNT(DISTINCT ?definition) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense [ skos:definition ?definition ] .
    FILTER(STR(?writtenRep) = "campo")
  }
}

PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?italianWord (COUNT(DISTINCT ?sense) AS ?count)
WHERE {
  SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
    ?word ontolex:canonicalForm [ ontolex:writtenRep ?writtenRep ] ;
          ontolex:sense ?sense .
    FILTER(STR(?writtenRep) = "banco" || STR(?writtenRep) = "piano" || STR(?writtenRep) = "campo" || STR(?writtenRep) = "punto")
  }

  ?word ontolex:canonicalForm ?italianLemma .

  GRAPH <http://liita.it/data> {
    ?italianLemma a lila:Lemma ;
                  ontolex:writtenRep ?italianWord .
  }
}
GROUP BY ?italianWord
ORDER BY DESC(?count)

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>

SELECT DISTINCT ?italianWord ?emotionLabel ?polarityValue ?parmigianoWord
WHERE {
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?plantaWord ontolex:canonicalForm [ ontolex:writtenRep ?plantaWr ] .
        FILTER(STR(?plantaWr) = "pianta")
        ?plantaWord ontolex:sense ?plantaSense .
        ?plantaSense lexinfo:hypernym ?hyponymSense .
        ?resultWord ontolex:sense ?hyponymSense .
    }

    ?resultWord ontolex:canonicalForm ?italianLemma .
    GRAPH <http://liita.it/data> {
        ?italianLemma a lila:Lemma ;
                      ontolex:writtenRep ?italianWord .
    }

    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
        ?emotion rdfs:label ?emotionLabel .
        FILTER(STR(?emotionLabel) = "Gioia")
    }

    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarity ?polarity ;
                   marl:hasPolarityValue ?polarityValue .

    ?parmigianoTransEntry ontolex:canonicalForm ?italianLemma ;
                          vartrans:translatableAs ?parmigianoLexEntry .
    ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                     ontolex:writtenRep ?parmigianoWord .
}
ORDER BY DESC(?polarityValue)

PREFIX dcterms: <http://purl.org/dc/terms/>
PREFIX elita: <http://w3id.org/elita/>
PREFIX lila: <http://lila-erc.eu/ontologies/lila/>
PREFIX lime: <http://www.w3.org/ns/lemon/lime#>
PREFIX marl: <http://www.gsi.upm.es/ontologies/marl/ns#>
PREFIX ontolex: <http://www.w3.org/ns/lemon/ontolex#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX vartrans: <http://www.w3.org/ns/lemon/vartrans#>
PREFIX lexinfo: <http://www.lexinfo.net/ontology/3.0/lexinfo#>

SELECT DISTINCT ?italianWord ?emotionLabel ?polarityValue ?sicilianWord ?parmigianoWord
WHERE {
    SERVICE <https://klab.ilc.cnr.it/graphdb-compl-it/> {
        ?pastaWord ontolex:canonicalForm [ ontolex:writtenRep ?pastaWr ] .
        FILTER(STR(?pastaWr) = "pasta")
        ?pastaWord ontolex:sense ?pastaSense .
        ?pastaSense lexinfo:hypernym ?hyponymSense .
        ?resultWord ontolex:sense ?hyponymSense .
    }

    ?resultWord ontolex:canonicalForm ?italianLemma .
    GRAPH <http://liita.it/data> {
        ?italianLemma a lila:Lemma ;
                      ontolex:writtenRep ?italianWord .
    }

    ?emotionEntry ontolex:canonicalForm ?italianLemma .
    GRAPH <http://w3id.org/elita> {
        ?emotionEntry elita:HasEmotion ?emotion .
        ?emotion rdfs:label ?emotionLabel .
        FILTER(STR(?emotionLabel) IN ("Gioia", "Felicità"))
    }

    ?polarityEntry ontolex:canonicalForm ?italianLemma ;
                   marl:hasPolarity ?polarity ;
                   marl:hasPolarityValue ?polarityValue .

    ?sicilianEntry ontolex:canonicalForm ?italianLemma ;
                   vartrans:translatableAs ?sicilianLexEntry .
    ?sicilianLexEntry ontolex:canonicalForm ?sicilianLemma .
    ?sicilianLemma dcterms:isPartOf <http://liita.it/data/id/DialettoSiciliano/lemma/LemmaBank> ;
                   ontolex:writtenRep ?sicilianWord .

    ?parmigianoEntry ontolex:canonicalForm ?italianLemma ;
                     vartrans:translatableAs ?parmigianoLexEntry .
    ?parmigianoLexEntry ontolex:canonicalForm ?parmigianoLemma .
    ?parmigianoLemma dcterms:isPartOf <http://liita.it/data/id/DialettoParmigiano/lemma/LemmaBank> ;
                     ontolex:writtenRep ?parmigianoWord .
}
ORDER BY DESC(?polarityValue)

